    ///   - thread: Thread ID (`thr_...`). The authenticated user must have permission to update this thread.
    ///   - input: Request body.
    /// - Returns: The thread object after the update has been applied.
    public func replace(thread: String, input: ThreadReplaceInput) async throws -> Thread {
