    ///
    /// - Parameters:
    ///   - thread: Thread ID (`thr_...`). Must be accessible to the authenticated user.
    /// - Returns: Successful response
    public func artifacts(thread: String) async throws -> ThreadArtifactsResponse {
        return try await http.request("/api/v1/threads/\(thread)/artifacts")
    }

