    ///   - thread: Thread ID (`thr_...`). Must be accessible to the authenticated user.
    ///   - q: Full-text search query. Results are ranked by relevance to this string.
    ///   - type: Context source type to restrict the search to, e.g. `"thread/messages"`. Omit to search across all context sources for the thread.
    /// - Returns: Successful response
    public func search(thread: String, q: String, type: String? = nil) async throws -> ThreadSearchResponse {
        var query: [(String, String)] = []
        query.append(("q", q))
        if let type = type {
            query.append(("type", type))
        }
        return try await http.request("/api/v1/threads/\(thread)/search", query: query)
    }
}
